import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.om2R87yU.js";const d=JSON.parse('{"title":"Pausing queues","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workers/pausing-queues.md","filePath":"guide/workers/pausing-queues.md","lastUpdated":1703221889000}'),l={name:"guide/workers/pausing-queues.md"};function n(p,e,r,o,u,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="pausing-queues" tabindex="-1">Pausing queues <a class="header-anchor" href="#pausing-queues" aria-label="Permalink to &quot;Pausing queues&quot;">​</a></h1><p>BullMQ supports pausing queues <em>globally</em> or <em>locally</em>. When a queue is paused <em>globally</em> no workers will pick up any jobs from the queue. When you pause a queue, the workers that are currently busy processing a job will continue working on that job until it completes (or fails), and then will keep idling until the queue is unpaused.</p><p>Pausing a queue is performed by calling the <em><strong><code>pause</code></strong></em> method on a <a href="/api/classes/v5.Queue.html" target="_self">queue</a> instance:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myQueue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>It is also possible to <em>locally</em> pause a given worker instance. This pause works in a similar way as the global pause in the sense that the worker will conclude processing the jobs it has already started but will not process any new ones:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myWorker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>The call above will wait for all the jobs currently being processed by this worker to complete (or fail). If you do not want to wait for current jobs to complete before the call completes you can pass <code>true</code> to pause the worker <strong>ignoring any running jobs</strong>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myWorker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="read-more" tabindex="-1">Read more: <a class="header-anchor" href="#read-more" aria-label="Permalink to &quot;Read more:&quot;">​</a></h2><ul><li>💡 <a href="/api/classes/v5.Queue.html#pause" target="_self">Pause Queue API Reference</a></li><li>💡 <a href="/api/classes/v5.Worker.html#pause" target="_self">Pause Worker API Reference</a></li></ul>',10)])])}const k=s(l,[["render",n]]);export{d as __pageData,k as default};
